    .error-subtext {
      font-size: 15px;
      color: #555555;
      margin-bottom: 28px;
      line-height: 1.55;
    }

    /* ─── SEARCH ─── */
    .search-form {
      display: flex;
      align-items: stretch;
      border: 1.5px solid #D1D5DB;
      border-radius: 6px;
      background: #ffffff;
      overflow: hidden;
      margin-bottom: 20px;
      transition: border-color 0.18s ease, box-shadow 0.18s ease;
    }

    .search-form:focus-within {
      border-color: #EB0028;
      box-shadow: 0 0 0 3px rgba(235, 0, 40, 0.10);
    }

    .search-input {
      flex: 1;
      min-width: 0;
      border: none;
      outline: none;
      padding: 13px 16px;
      font-size: 15px;
      font-family: inherit;
      color: #121212;
      background: transparent;
      caret-color: #EB0028;
    }

    .search-input::placeholder {
      color: #BBBBBB;
    }

    .search-btn {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 50px;
      flex-shrink: 0;
      background: #EB0028;
      border: none;
      cursor: pointer;
      color: #ffffff;
      transition: background-color 0.18s ease;
    }

    .search-btn:hover {
      background: #C9001F;
    }

    .search-btn:focus-visible {
      outline: 2px solid #EB0028;
      outline-offset: -3px;
    }

    /* ─── ERROR CODE BAR ─── */
    .error-code-bar {
      display: block;
      background: #F5F5F5;
      border-radius: 5px;
      padding: 11px 16px;
      font-size: 12.5px;
      font-weight: 400;
      color: #888888;
      letter-spacing: 0.4px;
      text-align: center;
      margin-bottom: 28px;
    }

    /* ─── DIVIDER ─── */
    .section-rule {
      border: none;
      border-top: 1px solid #EBEBEB;
      margin-bottom: 28px;
    }

    /* ─── NEXT STEPS ─── */
    .next-steps-label {
      font-size: 11px;
      font-weight: 600;
      color: #AAAAAA;
      letter-spacing: 1.2px;
      text-transform: uppercase;
      margin-bottom: 14px;
    }

    .nav-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .nav-list a {
      font-size: 15px;
      color: #777777;
      text-decoration: underline;
      text-decoration-color: rgba(119, 119, 119, 0.4);
      text-underline-offset: 3px;
      transition: color 0.18s ease, text-decoration-color 0.18s ease;
    }

    .nav-list a:hover {
      color: #444444;
      text-decoration-color: rgba(68, 68, 68, 0.6);
    }

    .nav-list a:focus-visible {
      outline: 2px solid #EB0028;
      outline-offset: 3px;
      border-radius: 2px;
    }

    /* ─── COOKIE BANNER ─── */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: #1A1A1A;
      color: #CCCCCC;
      padding: 16px 28px;
