      display: flex;
      align-items: center;
      gap: 24px;
      font-size: 13px;
      line-height: 1.5;
      border-top: 1px solid #2E2E2E;
      transition: transform 0.25s ease, opacity 0.25s ease;
    }

    .cookie-banner.hidden {
      transform: translateY(100%);
      opacity: 0;
      pointer-events: none;
    }

    .cookie-text {
      flex: 1;
      color: #BBBBBB;
    }

    .cookie-text a {
      color: #FFFFFF;
      text-decoration: underline;
      text-underline-offset: 2px;
      transition: opacity 0.15s;
    }

