      <p class="modal-desc" id="modal-desc">
        Manage your cookie preferences below. Essential cookies are always active — they
        are required for the site to function and cannot be disabled.
      </p>

      <!-- Essential (always on) -->
      <div class="pref-row">
        <div class="pref-info">
          <div class="pref-name">Essential Cookies</div>
          <div class="pref-desc">Required for core site functionality. These cannot be disabled.</div>
        </div>
        <label class="toggle">
          <input type="checkbox" checked disabled aria-label="Essential cookies (always active)">
          <span class="toggle-slider"></span>
        </label>
      </div>

      <!-- Analytics -->
      <div class="pref-row">
        <div class="pref-info">
          <div class="pref-name">Analytics</div>
          <div class="pref-desc">Help us understand how visitors use our platform so we can improve it.</div>
        </div>
        <label class="toggle">
          <input type="checkbox" id="pref-analytics" aria-label="Analytics cookies">
          <span class="toggle-slider"></span>
