  <script>
    (function () {
      'use strict';

      var STORAGE_KEY = 'ideaforum_cookie_consent';

      var banner  = document.getElementById('cookie-banner');
      var overlay = document.getElementById('modal-overlay');
      var manageBtn    = document.getElementById('manage-btn');
      var acceptBtn    = document.getElementById('accept-btn');
      var closeBtn     = document.getElementById('modal-close');
      var rejectAllBtn = document.getElementById('reject-all-btn');
      var savePrefsBtn = document.getElementById('save-prefs-btn');

      var prefAnalytics      = document.getElementById('pref-analytics');
      var prefPersonalization = document.getElementById('pref-personalization');
      var prefAdvertising    = document.getElementById('pref-advertising');

      /* ── Helpers ── */

      function hideBanner() {
        banner.classList.add('hidden');
      }

      function openModal() {
        overlay.classList.add('open');
        document.body.style.overflow = 'hidden';
        // Move focus into modal
        var firstFocusable = overlay.querySelector('button:not([disabled])');
        if (firstFocusable) firstFocusable.focus();
      }

      function closeModal() {
        overlay.classList.remove('open');
        document.body.style.overflow = '';
        manageBtn.focus();
      }

      function persist(prefs) {
        try {
          localStorage.setItem(STORAGE_KEY, JSON.stringify({
            analytics:      prefs.analytics,
            personalization: prefs.personalization,
            advertising:    prefs.advertising,
            savedAt:        Date.now()
          }));
        } catch (e) {}
      }

      function applyPrefs(prefs) {
        if (prefs.analytics      !== undefined) prefAnalytics.checked       = !!prefs.analytics;
        if (prefs.personalization !== undefined) prefPersonalization.checked  = !!prefs.personalization;
        if (prefs.advertising    !== undefined) prefAdvertising.checked     = !!prefs.advertising;
      }

      /* ── Actions ── */

      function acceptAll() {
        persist({ analytics: true, personalization: true, advertising: true });
        applyPrefs({ analytics: true, personalization: true, advertising: true });
        hideBanner();
      }

      function rejectAll() {
        persist({ analytics: false, personalization: false, advertising: false });
        applyPrefs({ analytics: false, personalization: false, advertising: false });
        hideBanner();
        closeModal();
      }

      function savePreferences() {
        persist({
          analytics:      prefAnalytics.checked,
          personalization: prefPersonalization.checked,
          advertising:    prefAdvertising.checked
        });
        hideBanner();
        closeModal();
      }

      /* ── Init: restore saved consent ── */

      try {
        var stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          var saved = JSON.parse(stored);
          applyPrefs(saved);
          hideBanner();
        }
      } catch (e) {}

      /* ── Events ── */

      manageBtn.addEventListener('click', openModal);
      acceptBtn.addEventListener('click', acceptAll);
      closeBtn.addEventListener('click', closeModal);
      rejectAllBtn.addEventListener('click', rejectAll);
      savePrefsBtn.addEventListener('click', savePreferences);

      // Close on backdrop click
      overlay.addEventListener('click', function (e) {
        if (e.target === overlay) closeModal();
      });

      // Close on Escape
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && overlay.classList.contains('open')) {
          closeModal();
        }
      });

      /* ── Search: redirect with query ── */

      document.getElementById('search-form').addEventListener('submit', function (e) {
        e.preventDefault();
        var q = this.querySelector('.search-input').value.trim();
        if (q) {
          window.location.href = '/search?q=' + encodeURIComponent(q);
        }
      });

    }());
  </script>

</body>
</html>
